const sumDisbursementsByEvent = `-- name: SumDisbursementsByEvent :one
SELECT COALESCE(sum(amount), 0)::bigint
FROM disbursements
WHERE event_id = $1 AND status IN ('approved', 'paid')
`

func (q *Queries) SumDisbursementsByEvent(ctx context.Context, eventID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, sumDisbursementsByEvent, eventID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const sumRefundedByPayment = `-- name: SumRefundedByPayment :one
SELECT COALESCE(sum(amount), 0)::bigint
FROM refunds
WHERE payment_id = $1 AND status = 'refunded'
`

func (q *Queries) SumRefundedByPayment(ctx context.Context, paymentID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, sumRefundedByPayment, paymentID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

